#!/bin/bash
## MANAGED BY ANSIBLE, DO NOT EDIT THIS FILE MANUALLY

SRVMSG=' =+= '
MSGGREEN='\033[0;32m'
MSGYELLOW='\033[0;33m'
MSGRED='\033[0;31m'
MSGNC='\033[0m'
RECOVERBOXYDIR="/etc/recoverybox"
REPODIR="/root/RecoveryBox"
TYPE="major"
FULL=false


yes_no_check () {
	if [ "$1" = "Y" ] || [ "$1" = "y" ] || [ "$1" = "Yes" ] || [ "$1" = "yes" ] || [ "$1" = "Oui" ] || [ "$1" = "OUI" ] || [ "$1" = "oui" ] || [ "$1" = "O" ]; then
		echo 1
	elif [ "$1" = "N" ] || [ "$1" = "n" ] || [ "$1" = "No" ] || [ "$1" = "no" ] || [ "$1" = "Non" ] || [ "$1" = "NON" ] || [ "$1" = "non" ] || [ "$1" = "N" ]; then
		echo 0
	else
		echo 99
	fi
}

Check_Update() {
    CurrentVersion=$(cat "$RECOVERBOXYDIR/rb_version" 2>/dev/null || echo "0.0.0")
    echo -e "${SRVMSG} ${MSGYELLOW}Current Recovery Box version: ${CurrentVersion}${MSGNC}"
    echo -e "${SRVMSG} ${MSGYELLOW} Checking for updates...${MSGNC}"
    if [[ $TYPE == "major" ]]; then
        LastVersion=$(curl -s https://api.github.com/repos/mr-dgidgi/recoverybox/releases/latest | grep -Po '"tag_name": "\K.*?(?=")')
    elif [[ $TYPE == "minor" ]]; then
        LastVersion=$(curl -s https://api.github.com/repos/mr-dgidgi/recoverybox/tags | grep '"name": "1.' | awk -F '"' '{print $4}' | head -n1)
    fi

    if [[ $CurrentVersion == "$LastVersion" ]]; then
        echo -e "${SRVMSG} ${MSGGREEN}Recovery Box is up to date.${MSGNC}"
        return 1
    else
        echo -e "${SRVMSG} ${MSGGREEN}New version available: ${LastVersion}"
        return 0
    fi
    
}

Download_Update() {
    echo -e "${SRVMSG} ${MSGYELLOW}Downloading Recovery Box version ${LastVersion}...${MSGNC}"
    if [[ -d "$REPODIR" ]]; then
        cd "$REPODIR" || exit 1
        git fetch --all >/dev/null 2>&1
        git reset --hard >/dev/null 2>&1
        git checkout "$LastVersion" >/dev/null 2>&1
    else
        echo -e "${SRVMSG} ${MSGRED}Missing $REPODIR folder ${MSGNC}"
        echo -e "${SRVMSG} ${MSGYELLOW}Cloning Recovery Box repository...${MSGNC}"
        git clone --depth 1 --branch "$LastVersion" https://github.com/mr-dgidgi/recoverybox.git "$REPODIR" >/dev/null 2>&1
        cd "$REPODIR" || exit 1
    fi
    echo -e "${SRVMSG} ${MSGGREEN}Recovery Box version ${LastVersion} downloaded.${MSGNC}"

}

Update_System() {
    echo -e "${SRVMSG} ${MSGYELLOW}Updating system packages...${MSGNC}"
    apt-get update -y >/dev/null 2>&1
    apt-get upgrade -y >/dev/null 2>&1
    if [[ $? -ne 0 ]]; then
        echo -e "${SRVMSG} ${MSGRED}System package update failed!${MSGNC}"
        exit 1
    else
        echo -e "${SRVMSG} ${MSGGREEN}System packages updated.${MSGNC}"
    fi
}

Update_RecoveryBox() {
    if ! cd "$REPODIR" ; then
        echo -e "${SRVMSG} ${MSGRED}Failed to change directory to $REPODIR${MSGNC}"
        exit 1
    fi
    if [[ ! -f "$REPODIR/RecoveryBox_install.sh" ]]; then
        echo -e "${SRVMSG} ${MSGRED}Recovery Box install script not found!${MSGNC}"
        exit 1
    fi
    bash "$REPODIR/RecoveryBox_install.sh"
}

main() {
    
    if ! Check_Update; then
        echo -e "${SRVMSG} ${MSGGREEN}No update needed.${MSGNC}"
        exit 0
    else
        read -rp "Do you want to update Recovery Box? (Y/N):" ChooseUpdate
        if [[ $(yes_no_check "$ChooseUpdate") -eq 1 ]]; then
            Download_Update
            if [[ $FULL == true ]]; then
                Update_System
            fi
            Update_RecoveryBox
        else
            echo -e "${SRVMSG} ${MSGYELLOW}RecoveryBox not updated${MSGNC}"
        fi
    fi
}

if [[ $1 == "--minor" ]]; then
    TYPE="minor"
elif [[ $1 == "--full" ]]; then
    FULL=true
elif [[ $1 == "--minor" ]] && [[ $2 == "--full" ]] || [[ $1 == "--full" ]] && [[ $2 == "--minor" ]]; then
    TYPE="minor"
    FULL=true
fi

main